const jobs = Array.isArray($json) ? $json : [];
const companies = [...new Set(jobs.map(j => j.company).filter(Boolean))];
if (!companies.length) return [{ json: { query: '', companies: [] } }];
// Build OR query: (from:company1 OR from:company2 ...) with outcome keywords
const companyQ = companies.slice(0, 15).map(c => `"${c}"`).join(' OR ');
const query = `(${companyQ}) (interview OR offer OR unfortunately OR regret OR "not selected" OR "move forward") newer_than:1d`;
return [{ json: { query, companies } }];

const emails = Array.isArray($json) ? $json : [$json];
const appliedJobs = $('GET Applied Jobs').all().map(i => i.json);

const rejectionKw = ['unfortunately','not moving forward','other candidates','regret to inform','not selected','position has been filled'];
const interviewKw = ['interview','pleased to invite','next steps','schedule a call'];
const offerKw    = ['offer','pleased to extend','job offer','compensation package'];

const results = [];
for (const email of emails) {
  const subj = (email.subject || '').toLowerCase();
  const from = (email.from || '').toLowerCase();
  const snippet = (email.snippet || '').toLowerCase();
  const body = subj + ' ' + from + ' ' + snippet;

  // Find matching applied job by company name in from/subject
  const matchedJob = appliedJobs.find(j => {
    const co = (j.company || '').toLowerCase();
    return body.includes(co) && co.length > 3;
  });
  if (!matchedJob) continue;

  let detectedOutcome = null;
  let emoji = '';
  if (offerKw.some(k => body.includes(k)))       { detectedOutcome = 'offer';     emoji = '🎊'; }
  else if (interviewKw.some(k => body.includes(k))) { detectedOutcome = 'interview'; emoji = '🎉'; }
  else if (rejectionKw.some(k => body.includes(k))) { detectedOutcome = 'rejected';  emoji = '👎'; }

  if (!detectedOutcome) continue;

  results.push({
    jobId: matchedJob.id,
    title: matchedJob.title,
    company: matchedJob.company,
    detectedOutcome,
    emoji,
    emailSubject: email.subject || '(no subject)',
    text: `${emoji} *Email detected from ${matchedJob.company}*\n"${email.subject || ''}"\n\nDetected outcome: *${detectedOutcome}*\n\nConfirm:\n/${detectedOutcome} ${matchedJob.id}  |  /ignore`
  });
}
return results.map(r => ({ json: r }));
